package com.codeguardian.service.tools; import com.codeguardian.entity.Finding; import java.util.*; public final class ReviewContextHolder{private static final ThreadLocal<List<Finding>> FINDINGS=ThreadLocal.withInitial(ArrayList::new);private ReviewContextHolder(){}public static void addAll(List<Finding> f){FINDINGS.get().addAll(f);}public static List<Finding> get(){return List.copyOf(FINDINGS.get());}public static void clear(){FINDINGS.remove();}}
